const code = ($json && $json.params && $json.params.code) ? $json.params.code.toString() : '';
const confirmUrl = '/webhook/mail-click-confirmar/' + encodeURIComponent(code);
const html = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>DoctoRed</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif; background: #DEE8D3; min-height: 100vh; display: flex; align-items: center; justify-content: center; padding: 24px; }
  .card { background: #FFFFFF; border-radius: 24px; padding: 40px 28px; max-width: 380px; width: 100%; text-align: center; box-shadow: 0 12px 40px rgba(65,24,120,0.12); }
  .brand { color: #411878; font-size: 26px; font-weight: 600; letter-spacing: -0.5px; margin-bottom: 6px; }
  h1 { color: #411878; font-size: 20px; font-weight: 600; margin-bottom: 12px; }
  p { color: #411878; opacity: 0.75; font-size: 15px; line-height: 1.5; margin-bottom: 28px; }
  .btn { display: block; background: #411878; color: #FFFFFF; text-decoration: none; font-size: 17px; font-weight: 600; padding: 16px; border-radius: 14px; }
</style>
</head>
<body>
  <div class="card">
    <div class="brand">DoctoRed</div>
    <h1>Estás a un paso</h1>
    <p>Tocá el botón para continuar.</p>
    <a class="btn" href="${confirmUrl}">Continuar</a>
  </div>
</body>
</html>`;
return [{ json: { html } }];

const raw = ($json && $json.params && $json.params.code) ? $json.params.code.toString() : '';
const ua = (($json && $json.headers && ($json.headers['user-agent'] || $json.headers['User-Agent'])) || '').toString().toLowerCase();
const idx = raw.lastIndexOf('-');
let baseCode = raw;
let wave = 1;
if (idx > -1) {
  baseCode = raw.slice(0, idx);
  const w = parseInt(raw.slice(idx + 1), 10);
  if (!isNaN(w)) wave = w;
}
const botPatterns = ['bot','crawl','spider','preview','facebookexternalhit','googlemessages','telegram','slack','discord','curl','wget','python','java/','go-http','okhttp','headless','prefetch','scan','monitor','pingdom','uptime','safelinks','outlook','gmailimageproxy','skype','line/','viber','twitterbot'];
const esBot = !ua || !ua.includes('mozilla') || botPatterns.some(p => ua.includes(p));
const esHumano = !esBot;
return [{ json: { baseCode, wave, ua, esHumano } }];

const pc = $('Parsear Codigo').first().json;
const baseCode = (pc.baseCode || '').toString().trim();
const wave = pc.wave;
const esHumano = pc.esHumano;
const normaliza = (v) => (v === undefined || v === null ? '' : v.toString().trim());
const match = $input.all().find(item => normaliza(item.json['codigo']) === baseCode && baseCode !== '');
const encontrado = !!match;
const marcar = encontrado && esHumano;
const out = { encontrado, esHumano, marcar, row_number: match ? match.json.row_number : null, wave, baseCode, destino: $('Config').first().json.LINK_DESTINO_MAIL };
if (marcar) {
  // EmailClick{wave} con timestamp -> corta las tandas de mail siguientes para este lead.
  out['EmailClick' + wave] = new Date().toISOString().slice(0, 19).replace('T', ' ');
}
return [{ json: out }];
